const BasicInformationComponent = (props) => {
  const navigate = useNavigate();
  const isEnabledMasterProposalType = props?.isEnabledMasterProposal;
  console.log(isEnabledMasterProposalType);
  // const modifiedProposalType = isEnabledMasterProposalType ? Utils.select_Quote_Type.map((option) =>
  //   option
  //   // option.value === 2 ? { ...option, isDisabled: true } : option
  // ) : Utils.select_Quote_Type.filter((option) => option.value !== 4);
  const modifiedProposalType = isEnabledMasterProposalType
    ? [...Utils.select_Quote_Type]
    : Utils.select_Quote_Type.filter((option) => option.value !== 4);

  const moduleNameForSaveAsDraft = "BasicInformation";
  const StatusId = 1;
  // proposal type select
  const selectedClientValue = props.clientLookUpOptions.filter(
    (item) => props.ProposalObject.clientID == item.value,
  );
  const selectedTemplateValue = props.templateLookUpOptions.filter(
    (item) => item.templateID === props.ProposalObject.templateID,
  );
  console.log(selectedTemplateValue);
  const selectedProposalValue = props.proposalLookUpOptions.filter(
    (item) => props.ProposalObject.selectedProposalTypeValue == item.value,
  );

  //Client Select Function
  const handleClientSelectChange = (selectedOption) => {
    props.DisableTabOnChange();
    props.setProposalObject({
      ...props.ProposalObject,
      clientID: selectedOption.value,
    });
    props.GetProposalEngLetterTemplateLookUpList(selectedOption.value);
  };

  // Template Select Function
  const handleTemplateSelectChange = (selectedOption) => {
    props.DisableTabOnChange();
    props.setTemplateElementList([]);
    props.setProposalObject({
      ...props.ProposalObject,
      selectTemplateTypeId: selectedOption.value,
      templateID: selectedOption.templateID,
    });
    const selectedTemplate = props.templateLookUpOptions.find(
      (item) => item.templateID === selectedOption.templateID,
    );
    if (selectedTemplate) {
      props.setHeaderContent(selectedTemplate.headerContent);
      props.setFooterContent(selectedTemplate.footerContent);
      props.setHeaderImage(selectedTemplate.headerImage);
      props.setFooterImage(selectedTemplate.footerImage);
      props.setPricingTableColumnIDs(selectedTemplate.pricingTableColumnIDs);
      props.setHeaderHeight(selectedTemplate.headerHeight);
      props.setFooterHeight(selectedTemplate.footerHeight);
      props.setFontFamily(props.getFontNameById(selectedTemplate.fontFamilyID));
      props.setShowSeparatorLines(selectedTemplate.showSeparatorLines);

      props.updateVisibleFieldsFromIds(selectedTemplate.pricingTableColumnIDs);

      props.setServiceDescriptionObj((prev) => ({
        ...prev,
        mainHeading: selectedTemplate?.mainHeadingSD,
        recurringOnGoingHeading: selectedTemplate?.recurringOnGoingHeadingSD,
        oneOffAdhocHeading: selectedTemplate?.oneOffAdhocHeadingSD,
        mainHeadingFontSize: selectedTemplate?.mainHeadingFontSizeSD,
        recurringOnGoingHeadingFontSize:
          selectedTemplate?.recurringOnGoingHeadingFontSizeSD,
        oneOffAdhocFontSize: selectedTemplate?.oneOffAdhocFontSizeSD,
        mainHeadingIsBold: selectedTemplate?.mainHeadingIsBoldSD,
        mainHeadingIsItalic: selectedTemplate?.mainHeadingIsItalicSD,
        recurringOnGoingHeadingIsBold:
          selectedTemplate?.recurringOnGoingHeadingIsBoldSD,
        recurringOnGoingHeadingIsItalic:
          selectedTemplate?.recurringOnGoingHeadingIsItalicSD,
        oneOffAdhocHeadingIsBold: selectedTemplate?.oneOffAdhocHeadingIsBoldSD,
        oneOffAdhocHeadingIsItalic:
          selectedTemplate?.oneOffAdhocHeadingIsItalicSD,
      }));
      props.setStatementOfFactsObj((prev) => ({
        ...prev,
        mainHeading: selectedTemplate?.mainHeadingSOF,
        recurringOnGoingHeading: selectedTemplate?.recurringOnGoingHeadingSOF,
        oneOffAdhocHeading: selectedTemplate?.oneOffAdhocHeadingSOF,
        mainHeadingFontSize: selectedTemplate?.mainHeadingFontSizeSOF,
        recurringOnGoingHeadingFontSize:
          selectedTemplate?.recurringOnGoingHeadingFontSizeSOF,
        oneOffAdhocFontSize: selectedTemplate?.oneOffAdhocFontSizeSOF,
        mainHeadingIsBold: selectedTemplate?.mainHeadingIsBoldSOF,
        mainHeadingIsItalic: selectedTemplate?.mainHeadingIsItalicSOF,
        recurringOnGoingHeadingIsBold:
          selectedTemplate?.recurringOnGoingHeadingIsBoldSOF,
        recurringOnGoingHeadingIsItalic:
          selectedTemplate?.recurringOnGoingHeadingIsItalicSOF,
        oneOffAdhocHeadingIsBold: selectedTemplate?.oneOffAdhocHeadingIsBoldSOF,
        oneOffAdhocHeadingIsItalic:
          selectedTemplate?.oneOffAdhocHeadingIsItalicSOF,
      }));
    }
  };

  //Select Proposal Type
  const handleProposalSelectChange = (selectedOption) => {
    props.setRecurringPricingInfo({
      ...props.RecurringPricingInfo,
      DefaultDiscount: "",
    });
    props.setOneOffPricingInfo({
      ...props.OneOffPricingInfo,
      DefaultDiscount: "",
    });
    props.setTabHide(false);
    props.DisableTabOnChange();
    props.setIsBack(
      selectedOption.value == props.ProposalObject.selectedProposalTypeValue,
    );
    props.setSelectedPackages([]);
    props.setSelectedPackagesDetails([]);
    props.setIsValidForm({
      ...props.isValidForm,

      SelectService: false,
      AdditionalInfo: false,
      PricingInfo: false,
      SelectPackages: false,
      ReviewPackages: false,
      ReviewService: false,
      Preview: false,
    });
    props.setProposalObject({
      ...props.ProposalObject,
      selectedProposalTypeValue: selectedOption.value,
    });
  };
  const handleAddClient = () => {
    navigate("/create-new-client", { state: { ModuleName: "Proposal" } });
  };
  return (
    <>
      <div className="create-practice-height scrollbar">
        <div className="tab-content">
          <div className="tab-pane p-3 active">
            <div className="row fieldset">
              <div className="col-md-3 mt-4  col-sm-12 text-start text-md-end">
                <label className="form-label">
                  Select {props.prospectName}
                </label>
                <span class="text-danger">*</span>
              </div>
              <div className="col-md-9 col-sm-12">
                <button
                  style={{
                    fontSize: "12px",
                    float: "right",
                    border: "none",
                    background: "transparent",
                    color: "#626ed4",
                  }}
                  className="float-sm-end"
                  onClick={handleAddClient}
                >
                  + Add New {props.prospectName}
                </button>

                <div className="mb-1 input-group">
                  <Select
                    className="user-role-select"
                    options={props.clientLookUpOptions}
                    value={selectedClientValue}
                    onChange={handleClientSelectChange}
                  />
                  {/* Validation error message for Client */}
                  {props.requireMessage &&
                  (props.ProposalObject.clientID === undefined ||
                    props.ProposalObject.clientID === null ||
                    props.ProposalObject.clientID === "") ? (
                    <span className="validation">{ERROR_MESSAGES}</span>
                  ) : (
                    ""
                  )}
                </div>
              </div>
            </div>
            <div className="row fieldset">
              <div className="col-md-3 col-sm-12 text-start text-md-end">
                <label className="form-label">Select Template</label>
                <span class="text-danger">*</span>
              </div>
              <div className="col-md-9 col-sm-12">
                <div className="mb-1 input-group">
                  <Select
                    className="user-role-select"
                    options={props.templateLookUpOptions}
                    value={selectedTemplateValue}
                    onChange={handleTemplateSelectChange}
                  />
                  {/* Validation error message for Template */}
                  {/* {props.requireMessage &&
                    (props.ProposalObject.selectTemplateTypeId === undefined ||
                      props.ProposalObject.selectTemplateTypeId === null ||
                      props.ProposalObject.selectTemplateTypeId === "") ? (
                    <span className="validation">{ERROR_MESSAGES}</span>
                  ) : (
                    ""
                  )} */}
                  {props.requireMessage &&
                  (!props.ProposalObject.templateID ||
                    props.ProposalObject.templateID === "") ? (
                    <span className="validation">{ERROR_MESSAGES}</span>
                  ) : null}
                </div>
              </div>
            </div>
            <div className="row fieldset">
              <div class="col-3 text-right">
                <label class="form-label text-nowrap">
                  Select {props.proposalName} Type
                  <span class="text-danger">*</span>
                </label>
              </div>
              <div className="col-md-9 col-sm-12">
                <div className="mb-3">
                  <div className="mb-1 input-group">
                    <Select
                      className="user-role-select"
                      // options={Utils.select_Quote_Type}
                      options={modifiedProposalType}
                      value={props.ProposalType}
                      onChange={handleProposalSelectChange}
                    />
                    {props.requireMessage &&
                    (props.ProposalObject.selectedProposalTypeValue ===
                      undefined ||
                      props.ProposalObject.selectedProposalTypeValue === null ||
                      props.ProposalObject.selectedProposalTypeValue === "") ? (
                      <span className="validation">{ERROR_MESSAGES}</span>
                    ) : (
                      ""
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div class="separator"></div>
      <div class="row fieldset">
        <div class="col-lg-12 hstack  gap-2 justify-content-end text-right mt-3">
          <button
            class="btn btn-md btn-light"
            onClick={() => props.handleCancelBtn()}
          >
            <span>Cancel</span>
          </button>
          <button
            class="btn btn-md btn-success create-item-btn"
            // onClick={() => props.HandleTabChange(2)}
            onClick={() => props.HandleTabChange(2)}
          >
            <span>Next</span>
          </button>
          <button
            class="btn btn-md btn-success create-item-btn  text-nowrap"
            onClick={() =>
              props.handleSaveAsDraft(1, moduleNameForSaveAsDraft, StatusId)
            }
          >
            <span>Save As Draft</span>
          </button>
        </div>
      </div>
    </>
  );
};
