  const handleResendQuote = async () => {
    setLoader(true);
    try {
      const res = await ResendAddUpdateQuote(
        common.userKeyID,
        // ProposalObject?.quoteKeyID ? ProposalObject?.quoteKeyID : null
        common.organisationKeyID,
      );

      if (res.data.statusCode === 200) {
        setLoader(false);
        setOpenEmailFailurePopUp(false);
        setProposalObject((prev) => ({
          ...prev,
          Action: "ResendAddUpdateQuote",
        }));
        setOpenSuccessModal(true);
        // navigate("/proposals");
      } else {
        const EmailStausData = await GetProspectSendMailStatus(
          common.userKeyID,
          common.organisationKeyID,
          "AddUpdateQuote",
          "Temp Key Id",
        );

        setLoader(false);
        setEmailCheckModel((prev) => ({
          ...prev,
          MethodName: "All Email Failed",
        }));
        if (!EmailStausData?.data?.responseData) {
          setOpenEmailFailurePopUp(true);
        }
      }
    } catch (error) {
      setLoader(false);
      console.log(error);
    }
  };

  // Handle save As A Draft And Send Proposal
  const AddUpdateQuat = async (params, StatusId) => {
    if (
      ProposalObject.paymentGatewayID ===
        ChangeDefaultPaymentGatewaysTypes.Stripe &&
      ProposalObject?.ProposalFormate === 1
    ) {
      if (
        isValueGreaterThan20000(
          RecurringPricingInfo,
          OneOffPricingInfo,
          vatPercentage,
          selectedPackages,
        )
      ) {
        setLoader(false);
        setErrorMessage(
          `Stripe cannot be selected as the payment method because your total exceeds ${props.currencySymbol}20,000. Please choose another payment method.`,
        );
        setOpenErrorModal(true);
        return;
      }
    }

    try {
      const URL = "/AddUpdateQuote";
      const data = await AddUpdateQuote(URL, params);
      if (data?.data?.statusCode === 200) {
        // console.log(EmailStausData.data.responseData); //if false then mail is not sent if true then mail is sent.
        if (statusID === statusID.Sent) {
          if (!data?.data?.responseData?.isEmailSent[0]?.isMailSent) {
            const EmailStausData = await GetProspectSendMailStatus(
              common.userKeyID,
              common.organisationKeyID,
              "AddUpdateQuote",
              "Temp Key Id",
            );
            if (!EmailStausData?.data?.responseData) {
              setEmailCheckModel((prev) => ({
                ...prev,
                ModuleName: "PL",
              }));
              setOpenEmailFailurePopUp(true);
            }
          }
        }
        setLoader(false);
        setOpenSuccessModal(true);
        if (data?.data?.responseData && data.data?.responseData?.refID) {
          const refID = data.data?.responseData?.refID;
          setRefIdStore(refID);
        }

        if (StatusId === 3) {
          navigate("/add-engagement-letter", {
            state: { QuoteKeyID: data?.data?.responseData?.data },
          });
        }
        setOpenSuccessModal(true);
      } else {
        let Errormessage = data?.data?.errorMessage;
        if (data?.response?.data?.statusCode === 500) {
          Errormessage = data?.response?.data?.errorMessage;
        }
        if (Errormessage.includes("Arithmetic overflow")) {
          setErrorMessage(
            "The result of this operation is too large to be processed. Please check the input values and try again.",
          );
          setOpenErrorModal(true);
        } else {
          setErrorMessage(data?.data?.errorMessage);
        }

        setLoader(false);
      }
      if (statusID === statusID.Sent) {
        if (data.response.data.errorMessage === "Client - Send Mail Failed") {
          // Call Get prospect send mail status api
          const EmailStausData = await GetProspectSendMailStatus(
            common.userKeyID,
            common.organisationKeyID,
            "AddUpdateQuote",
            "Temp Key Id",
          );
          if (!EmailStausData.data.responseData) {
            setOpenEmailFailurePopUp(true);
          }
        }
      }
    } catch (error) {
      console.error(error);
      setLoader(false);
    } finally {
      setLoader(false);
    }
  };
